# pART7 · hill grass matches the physics ground (±0.05 m) everywhere it is drivable (module art7.js)
# - gndBuild: non-river ground cells split as an adaptive quadtree (art7.js) instead of one uniform n×n grid capped at 8 m steps,
#   whose 5×5-point error check missed the hills' finer relief (grass up to 0.4 m off groundAt);
# - river-bank cells (Sachsenhäuser Berg down to the Main) took the 25 m river step and skipped the hill check: now a verified ≤ 3 cm step;
# - quadtree leaves share vertices within a mesh (no extra vertex cost over the triangles);
# - outer land (Stadtwald etc.) sat 0.25 m under the physics ground: now 1 cm like the city box, pushed back by polygonOffset at seams.
exec(open('P.py').read());exec(open('artlib.py').read())
ART_mod('art7.js')
RR("function gndBuild(grp,x0,x1,z0,z1,o){const B=new Map(),cs=o.cs,nx=Math.round((x1-x0)/cs),nz=Math.round((z1-z0)/cs),dx=(x1-x0)/nx,dz=(z1-z0)/nz;\n  for(let i=0;i<nx;i++)for(let j=0;j<nz;j++){const ax=x0+i*dx,az=z0+j*dz,cx=ax+dx/2,cz=az+dz/2;if(o.hole&&o.hole(cx,cz))continue;\n    let n=1,f=cs;if(rivClear(cx,cz)<Math.hypot(dx,dz)/2+o.fine*1.5){n=Math.ceil(dx/o.fine);f=o.fine}else if(o.hilly){const hv=o.hilly(ax,ax+dx,az,az+dz);if(hv){n=Math.ceil(dx/(hv===true?20:hv));f=dx/n}}\n    const k=o.cls(cx,cz),key=k+'|'+Math.floor((cx-x0)/o.tile)+'|'+Math.floor((cz-z0)/o.tile);let G=B.get(key);if(!G)B.set(key,G={k,p:[],u:[],c:[],n:[],i:[]});\n    const V=[],sx=dx/n,sz=dz/n;for(let a=0;a<=n;a++)for(let b=0;b<=n;b++)V.push(n>1?gndVert(ax+a*sx,az+b*sz,o.y0,f):[ax+a*sx,o.y0+tH(ax+a*sx,az+b*sz),az+b*sz,0]);\n    const base=G.p.length/3;for(const v of V){G.p.push(v[0],v[1],v[2]);G.u.push(v[0]/o.uv,v[2]/o.uv);if(o.col){const c=o.col(v[0],v[2]);G.c.push(c.r,c.g,c.b)}\n      if(v[3])G.n.push(0,1,0);else{const e=2,hx=tH(v[0]+e,v[2])-tH(v[0]-e,v[2]),hz=tH(v[0],v[2]+e)-tH(v[0],v[2]-e),l=Math.hypot(hx,2*e,hz);G.n.push(-hx/l,2*e/l,-hz/l)}}\n    for(let a=0;a<n;a++)for(let b=0;b<n;b++){const q=a*(n+1)+b;if(V[q][3]&&V[q+1][3]&&V[q+n+1][3]&&V[q+n+2][3])continue;G.i.push(base+q,base+q+1,base+q+n+1,base+q+1,base+q+n+2,base+q+n+1)}}\n  const out=[];for(const G of B.values()){if(!G.i.length)continue;const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(G.p,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(G.n,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(G.u,2));if(o.col)g.setAttribute('color',new THREE.Float32BufferAttribute(G.c,3));g.setIndex(G.i);\n    const m=new THREE.Mesh(g,o.mats[G.k]);m.receiveShadow=true;grp.add(m);out.push(m)}return out}","function gndBuild(grp,x0,x1,z0,z1,o){const B=new Map(),cs=o.cs,nx=Math.round((x1-x0)/cs),nz=Math.round((z1-z0)/cs),dx=(x1-x0)/nx,dz=(z1-z0)/nz;\n  for(let i=0;i<nx;i++)for(let j=0;j<nz;j++){const ax=x0+i*dx,az=z0+j*dz,cx=ax+dx/2,cz=az+dz/2;if(o.hole&&o.hole(cx,cz))continue;\n    let n=1,f=cs,Q=null;if(rivClear(cx,cz)<Math.hypot(dx,dz)/2+o.fine*1.5){n=Math.ceil(dx/o.fine);f=o.fine;if(o.hilly){const m=ART7_res(ax,ax+dx,az,az+dz);if(m>n){n=m;f=dx/n}}}else if(o.hilly){Q=[];ART7_quad(ax,az,dx,dz,Q)}\n    const k=o.cls(cx,cz),key=k+'|'+Math.floor((cx-x0)/o.tile)+'|'+Math.floor((cz-z0)/o.tile);let G=B.get(key);if(!G)B.set(key,G={k,p:[],u:[],c:[],n:[],i:[],m:new Map()});\n    for(const[lx,lz,lw,lh]of Q||[[ax,az,dx,dz]]){if(Q){n=1;f=lw}\n    const V=[],sx=lw/n,sz=lh/n;for(let a=0;a<=n;a++)for(let b=0;b<=n;b++)V.push(n>1?gndVert(lx+a*sx,lz+b*sz,o.y0,f):[lx+a*sx,o.y0+tH(lx+a*sx,lz+b*sz),lz+b*sz,0]);\n    const ix=[];for(const v of V){const kk=Q?Math.round(v[0]*16)+','+Math.round(v[2]*16):null;if(kk!==null&&G.m.has(kk)){ix.push(G.m.get(kk));continue}ix.push(G.p.length/3);if(kk!==null)G.m.set(kk,G.p.length/3);G.p.push(v[0],v[1],v[2]);G.u.push(v[0]/o.uv,v[2]/o.uv);if(o.col){const c=o.col(v[0],v[2]);G.c.push(c.r,c.g,c.b)}\n      if(v[3])G.n.push(0,1,0);else{const e=2,hx=tH(v[0]+e,v[2])-tH(v[0]-e,v[2]),hz=tH(v[0],v[2]+e)-tH(v[0],v[2]-e),l=Math.hypot(hx,2*e,hz);G.n.push(-hx/l,2*e/l,-hz/l)}}\n    for(let a=0;a<n;a++)for(let b=0;b<n;b++){const q=a*(n+1)+b;if(V[q][3]&&V[q+1][3]&&V[q+n+1][3]&&V[q+n+2][3])continue;G.i.push(ix[q],ix[q+1],ix[q+n+1],ix[q+1],ix[q+n+2],ix[q+n+1])}}}\n  const out=[];for(const G of B.values()){if(!G.i.length)continue;const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(G.p,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(G.n,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(G.u,2));if(o.col)g.setAttribute('color',new THREE.Float32BufferAttribute(G.c,3));g.setIndex(G.i);\n    const m=new THREE.Mesh(g,o.mats[G.k]);m.receiveShadow=true;grp.add(m);out.push(m)}return out}")
